public class Program
{
    public static void Main(string[] args)
    {
        var builder = WebApplication.CreateBuilder(args);

        builder.Services.AddDbContext<AppDbContext>(options =>
            options.UseSqlServer(builder.Configuration.GetConnectionString("DefaultConnection")));

        builder.Services.AddIdentity<ApplicationUser, IdentityRole>(options =>
            {
                options.Password.RequireDigit = true;
                options.Password.RequiredLength = 8;
                options.Password.RequireNonAlphanumeric = true;
            })
            .AddEntityFrameworkStores<AppDbContext>()
            .AddDefaultTokenProviders();

        var app = builder.Build();
    }
}

[Authorize(Roles = "Admin,Manager")]
[ApiController]
[Route("api/[controller]")]
public class ReportsController : ControllerBase
{
    [HttpGet]
    public IActionResult GetSalesReport()
    {
        // Only Admin and Manager roles can access this
        return Ok(new { Report = "Q4 Sales Report", Total = 150000 });
    }
}

[Authorize(Roles = "Admin")]
public class AdminController : ControllerBase
{
    [HttpPost("users/{userId}/roles")]
    public async Task<IActionResult> AssignRole(string userId, string role)
    {
        var user = await _userManager.FindByIdAsync(userId);
        await _userManager.AddToRoleAsync(user, role);
        return Ok();
    }
}

public class ReportService
{
    private readonly IHttpContextAccessor _httpContextAccessor;

    public ReportService(IHttpContextAccessor httpContextAccessor)
    {
        _httpContextAccessor = httpContextAccessor;
    }

    public bool CanViewSensitiveReports()
    {
        var user = _httpContextAccessor.HttpContext?.User;
        return user != null && (user.IsInRole("Admin") || user.IsInRole("Manager"));
    }
}

